/* FunctionMapper.updateCarryin : 오더 반입적용 */
UPDATE TB_ECM_OD_ADDITIONAL
SET
    LAST_POD_STATUS = #{insStatus}

WHERE OD_JOB_NO IN (#{item.odJobNo})
AND ISNULL(LAST_POD_STATUS,'') <> 'ECM040'
AND ISNULL(LAST_POD_STATUS,'') < #{insStatus}

/* FunctionMapper.updatePodInfo : POD 업데이트 */
UPDATE TB_ECM_POD SET
	UPDATE_USER_ID	= #{updateUserId}
	,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())	
	,POD_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())
	,POD_TIME = CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108)
WHERE POD_JOB_NO = #{POD_JOB_NO}
AND POD_STATUS = #{POD_STATUS};


UPDATE TB_ECM_POD_01 SET
	UPDATE_USER_ID	= #{updateUserId}
	,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())	
	,POD_DATE = DATEADD(HOUR, ${gmtTime}, GETDATE())
	,POD_TIME = CONVERT(VARCHAR(5), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108)
WHERE POD_JOB_NO = #{POD_JOB_NO}
AND POD_STATUS = #{POD_STATUS};

/* FunctionMapper.insertPodInfo : POD 인서트 */

INSERT INTO TB_ECM_POD_01 (
 	 POD_JOB_NO
 	,ENT_CODE
 	,OD_JOB_NO
 	,POD_STATUS
 	,POD_DATE
 	,POD_TIME
 	,BL_NO
 	,REGISTER_USER_ID
 	,REGISTER_DATE_TIME
 	,UPDATE_USER_ID
 	,UPDATE_DATE_TIME
) VALUES (
	 #{POD_JOB_NO}
    ,#{entCode}
	,#{odJobNo}
    ,#{POD_STATUS}
    ,DATEADD(HOUR, ${gmtTime}, GETDATE())
    ,SUBSTRING(CONVERT(VARCHAR(10), DATEADD(HOUR, ${gmtTime}, GETDATE()), 108), 1, 5)
    ,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),'')))		
    ,#{updateUserId}
    ,DATEADD(HOUR, ${gmtTime}, GETDATE())
    ,#{updateUserId}
    ,DATEADD(HOUR, ${gmtTime}, GETDATE())
);

/* FunctionMapper.deletePodInfo : POD 삭제 */
DELETE TB_ECM_POD
WHERE ENT_CODE = #{entCode}
AND OD_JOB_NO IN (#{item.odJobNo})
AND POD_STATUS = #{delStatus};

DELETE TB_ECM_POD_01
WHERE ENT_CODE = #{entCode}
AND OD_JOB_NO IN (#{item.odJobNo})
AND POD_STATUS = #{delStatus};

/* FunctionMapper.updateLastPodStatus : LAST_POD_STATUS 업데이트 */
UPDATE TB_ECM_OD_ADDITIONAL
SET LAST_POD_STATUS = #{insStatus}

WHERE OD_JOB_NO IN (#{item.odJobNo})
AND ISNULL(LAST_POD_STATUS,'') < #{insStatus}

/* FunctionMapper.updateObDate : 오더 입항일자 적용 */
UPDATE TB_ECM_OD
SET OB_DATE = #{obDate}	
WHERE ENT_CODE = #{entCode}
AND OD_JOB_NO IN (#{item.odJobNo})

/* FunctionMapper.updatePenalty : 오더 패널티 업데이트 */
UPDATE TB_ECM_OD
SET PENALTY_YN = #{penaltyYn}	
WHERE ENT_CODE = #{entCode}
AND OD_JOB_NO = #{odJobNo}
AND BL_TYPE_MH = 'H'
